// Class for a corridor segment
class CorridorSegment {
  constructor(z) {
    this.z = z;
		this.clr = color(240);
  }

  update(lightClr) {
    this.z += 15 // Speed
		this.lightClr = lightClr;
  }

  display() {
		// lightFalloff(0.1, 0.1, 0); // [constant, linear, quadratic]
    // pointLight(255, 255, 255, 0, 0, 0); // White light at camera

		const dlt = corridorWidth / 2;

    push();
    translate(0, 0, this.z);

		if (true) {
			// Floor
			fill(224)
			noStroke();
			push();
			translate(0, corridorHeight / 2, 0);
			box(corridorWidth, 10, segmentDepth);
			fill(32);
			translate(-dlt, 0, 0)
			box(40, 20, segmentDepth)
			translate(dlt+dlt, 0, 0)
			box(40, 20, segmentDepth)
			pop();

			// ceiling
			push();
			fill(212)
			translate(0, -corridorHeight / 2, 0);
			box(corridorWidth, 10, segmentDepth);
			fill(64);
			translate(-dlt, 0, 0)
			box(40, 20, segmentDepth)
			translate(dlt+dlt, 0, 0)
			box(40, 20, segmentDepth)
			pop();
		} 

		// walls (left and right with lights) 
		push();
		this.drawWalls(dlt);
		pop();

    pop();
  }

	drawWalls(dlt) {
		noStroke();
		const wandClr = lerpColor(this.clr, this.lightClr, 0.05);

		push();
		translate(-dlt, 0, 0);
		rotateY(HALF_PI);
		fill(wandClr);
		plane(corridorHeight, segmentDepth);
		fill(128);
		translate(segmentDepth/2, 0, 1)
		plane(corridorHeight/40, segmentDepth);
		pop()

		push()
		translate(dlt, 0, 0);
    rotateY(-HALF_PI);
		fill(wandClr);
		plane(corridorHeight, segmentDepth);
		fill(32);
		translate(0, 0, 1)
		plane(corridorHeight/40, segmentDepth);
		pop();

		// light
		push()
		const sz = min(corridorHeight, segmentDepth) * 0.1
		translate(0, -corridorHeight / 2, segmentDepth / 2)
		let clr = color("cyan");
		if (this.lightClr !== null) {
			clr = this.lightClr;
			pointLight(clr, 0, dlt/4, 0);
			// spotLight(clr, 0, 0, 0)
			spotLight(color("white"), createVector(0,dlt/4, 0), createVector(0, 1, 0), PI/8, 100);
		}
		fill(clr);
		// sphere(sz);
		box(dlt*1.2, 20, dlt*0.6)
		pop()
	} // drawWalls()

}


