let corridorLength = 2000
let corridorWidth = 400
let corridorHeight = 600

let segments = []
let numSegments = 16
let segmentDepth = corridorHeight; // 400
let off = 0;

async function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
	describe("moving thru severance floors with flickering lights");
	frameRate(60);
	pixelDensity(1);

	// Initialize the corridor segments
  for (let i = 0; i < numSegments; i++) {
    const z = -i * segmentDepth
    segments.unshift(new CorridorSegment(z))
  }
}

function draw() {
  background(96);
  noFill();
  stroke(32, 32);
	line(0, -height, 0, height)

	push();

  // Move camera forward
  camera(0, 0, 0, 0, 0, -1, 0, 1, 0)

  // Add lighting setup
	ambientLight(224, 224, 240);

  // Update and display each segment

	let firstSeg = true;
  for (let i = 0; i < segments.length; i++) {
		const seg = segments[i];
		const n = noise(off-i, frameCount/128);
		var clr = color("white");
		if (n > 0.2) clr = lerpColor(color(0), color("white"), map(n, 0, 0.6, 0, 1));
		if (n > 0.6) clr = lerpColor(color("red"), color("black"), map(n, 0.6, 1, 0, 1));
    seg.update(clr);
    seg.display();
		firstSeg = false;
  }
	pop()

  // Now handle segment recycling separately
  while (segments[segments.length - 1].z > 100) {
    let removed = segments.pop();
    let newZ = segments[0].z - segmentDepth;
    segments.unshift(new CorridorSegment(newZ));
		off++
  }

	// lift
	push();
	noStroke();
	// fill(lerpColor(color("red"), color("darkred"), noise(PI, frameCount/PI/PI)));
	fill(noise(PI, frameCount/PI/PI) < 0.5 ? 0 : "darkred")
	translate(0, -70, -corridorLength*1.5);
	rotateY(frameCount/64)
	cone(25, 45, 5);
	pop();
	// console.log(segments.length)
}
